def effect(v):return f"{v['estimate']:+.4f} [{v['lower_95']:+.4f}, {v['upper_95']:+.4f}]"
def interpretation(v):return 'supported improvement' if v['lower_95']>0 else ('supported deterioration' if v['upper_95']<0 else 'inconclusive difference')
def exact(path):
 p=Path(path);return identity(p)
def put(p,text):
 p.parent.mkdir(parents=True,exist_ok=True)
 with p.open('x') as f:f.write(text)
def csvwrite(p,rows):
 with p.open('x',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)

