  for name,r in report['models'].items():
   if any(row['task']==task and row['model']==name for row in clean):continue
   clean.append({'task':task,'model':name,**{m:r['metrics'][m]['estimate'] for m in METRICS}})
   registry.append({'task':task,'model':name,'status':'COMPLETE','report':exact(sources[label]),'folds':r['folds'],'seeds':r['seeds']})
